import random

def is_antimagic(grid):
    sums = []
    for i in range(5):
        sums.append(sum(grid[i*5 + j] for j in range(5)))
    for j in range(5):
        sums.append(sum(grid[i*5 + j] for i in range(5)))
    sums.append(sum(grid[i*5 + i] for i in range(5)))
    sums.append(sum(grid[i*5 + (4-i)] for i in range(5)))

    if len(set(sums)) != 12:
        return None

    if max(sums) - min(sums) != 11:
        return None

    return sums

def solve_randomized():
    nums = list(range(1, 26))
    for _ in range(1000000):
        random.shuffle(nums)
        sums = is_antimagic(nums)
        if sums:
            return nums + sums
    return None

print(solve_randomized())
